local M=require('retgtk.core');return function(p) local w=M.widget('image',p);function w:paint(r,c) local a=self.pixels or {};local cols,rows=self.columns or 1,self.rows or 1;assert(cols>0 and rows>0 and cols*rows<=4096);for j=1,rows do for i=1,cols do local v=a[(j-1)*cols+i];if v then imm_rect(r.x+(i-1)*r.w/cols,r.y+(j-1)*r.h/rows,r.w/cols,r.h/rows,v) end end end end;return w end
